}
#escenario .form-check-label {
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--muted);
  padding: 8px 12px;
  border-radius: 999px;
  font-size: 0.82rem;
  cursor: pointer;
  transition: all 0.2s ease;
}
#escenario .form-check-input { display: none; }
#escenario .form-check-input:checked + .form-check-label {
  background: var(--brand-dim);
  border-color: var(--brand);
  color: var(--brand);
  font-weight: 600;
}

/* Detalles técnicos */
.detalles-tecnicos { margin-top: 16px; }
.detalles-fila {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}
.detalles-fila span {
  background: var(--surface-2);
  border: 1px solid var(--border);
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 0.78rem;
  color: var(--muted);
  font-family: "JetBrains Mono", monospace;
}
.detalles-fila b { color: var(--text); }
.nota-unicode {
  display: block;
  width: 100%;
  color: var(--warning);
  border-color: rgba(255, 176, 32, 0.35);
}
/* Estado "no calculable" del panel de detalles (vacía / solo unicode) */
.detalle-na {
  margin: 8px 0 0;
  text-align: center;
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}

/* --- Dato curioso (tarjeta con ícono) --- */
.tarjeta-dato {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  animation: subir 0.4s ease both;
}
.dato-icono {
  flex-shrink: 0;
  width: 46px; height: 46px;
  border-radius: 12px;
  background: var(--brand-dim);
  color: var(--brand);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
}
.dato-cuerpo {
  flex: 1;
  min-width: 0;
}
.dato-texto {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.05rem;
  line-height: 1.5;
  color: var(--text);
}

/* --- Sugerencias --- */
#panel-sugerencias .tarjeta-titulo { margin-bottom: 6px; }
.sugerencia-vacia { color: var(--muted); padding: 12px 0; font-size: 0.9rem; }
.sugerencia {
  display: flex;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
  animation: subir 0.45s ease both;
}
.sugerencia:last-child { border-bottom: none; }
.sugerencia-num {
  flex-shrink: 0;
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--brand);
  font-weight: 700;
  font-family: "Space Grotesk", sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}
.sugerencia-cuerpo { flex: 1; min-width: 0; }
.sugerencia-cuerpo strong {
  font-family: "Space Grotesk", sans-serif;
  font-size: 0.95rem;
  color: var(--text);
}
.sugerencia-cuerpo p { color: var(--muted); font-size: 0.88rem; line-height: 1.5; margin: 4px 0 8px; }
.sugerencia-antes-despues {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 0.82rem;
}
.badge-antes, .badge-despues {
  padding: 5px 10px;
  border-radius: 8px;
  font-family: "JetBrains Mono", monospace;
}
.badge-antes  { background: rgba(255, 93, 93, 0.12); color: var(--danger); }
.badge-despues { background: var(--brand-dim); color: var(--brand); }
.sugerencia-antes-despues i { color: var(--muted); font-size: 0.7rem; }
.sugerencia-nota { margin-top: 6px; color: var(--muted); font-size: 0.78rem; font-style: italic; }
.sugerencia-diccionario .sugerencia-num { color: var(--danger); border-color: rgba(255, 93, 93, 0.4); }
.sugerencia-leetspeak .sugerencia-num { color: var(--warning); border-color: rgba(255, 176, 32, 0.4); }
.sugerencia-fuerte .sugerencia-num { color: var(--brand); }

/* --- Compartir --- */
.compartir { text-align: center; }
.btn-compartir {
  background: var(--brand);
  color: #06120d;
  border: none;
  font-weight: 700;
  border-radius: 12px;
  padding: 12px 22px;
  font-size: 0.95rem;
  transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.btn-compartir:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--brand-dim); color: #06120d; }
.btn-compartir:active { transform: translateY(0); }
.compartir-nota { margin-top: 8px; color: var(--brand); font-size: 0.85rem; min-height: 1.2em; }

/* --- Pie --- */
.pie { color: var(--muted); font-size: 0.75rem; line-height: 1.6; text-align: center; padding: 8px 16px 0; }

/* --- Animaciones --- */
@keyframes subir {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* --- Responsive (desktop: más aire) --- */
@media (min-width: 768px) {
  .contenedor { padding: 48px 24px 64px; gap: 20px; }
  .tarjeta { padding: 26px; }
  .fila-input { flex-direction: row; align-items: end; }
  .fila-input #password { flex: 1; }
  .fila-input .form-check { margin-bottom: 12px; white-space: nowrap; }
}
